<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\{ExamAccess,SchoolAssessments,ExamReports,StudentImportReader};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class ExamsController extends Controller {
 public function __construct(private ExamAccess $exam,private SchoolAssessments $assessments,private ExamReports $reports){}
 public function setup(Request $r){return response()->json($this->assessments->setup($r));}
 public function scheme(Request $r){$this->exam->context($r);$d=$r->validate(['name'=>'required|string|min:2|max:100','passing_percent'=>'required|numeric|min:0|max:100|decimal:0,2','rounding_policy'=>['required',Rule::in(['two_decimals','whole_percent'])],'tie_policy'=>['required',Rule::in(['competition','dense','none'])],'bands'=>'required|array|min:2|max:12','bands.*.label'=>'required|string|max:20','bands.*.min_percent'=>'required|numeric|min:0|max:100|decimal:0,2']);return response()->json($this->assessments->gradeScheme($r,$d));}
 public function cycle(Request $r){$this->exam->context($r);$d=$r->validate(['section_id'=>'required|integer','name'=>'required|string|min:2|max:160','starts_on'=>'required|date_format:Y-m-d','ends_on'=>'required|date_format:Y-m-d|after_or_equal:starts_on','academic_term_id'=>'nullable|integer','grading_scheme_id'=>'required|integer']);return response()->json($this->assessments->cycle($r,$d));}
 public function weights(Request $r){$this->exam->context($r);$d=$r->validate(['section_id'=>'required|integer','exam_cycle_id'=>'required|integer','subject_id'=>'required|integer','lock_version'=>'required|integer|min:0','weights'=>'required|array|min:1|max:5','weights.*.assessment_type'=>['required','distinct',Rule::in(SchoolAssessments::TYPES)],'weights.*.weight'=>'required|numeric|min:0|max:100|decimal:0,2']);return response()->json($this->assessments->weights($r,$d));}
 public function tests(Request $r){$d=$r->validate(['section_id'=>'nullable|integer','exam_cycle_id'=>'nullable|integer','page'=>'nullable|integer|min:1']);return response()->json($this->assessments->list($r,$d));}
 public function test(Request $r,?int $id=null){$this->exam->context($r);$d=$r->validate(['section_id'=>'required|integer','subject_id'=>'required|integer','exam_cycle_id'=>'nullable|integer','grading_scheme_id'=>'required|integer','title'=>'required|string|min:2|max:160','test_date'=>'required|date_format:Y-m-d','max_marks'=>'required|numeric|gt:0|max:100000|decimal:0,2','passing_marks'=>'required|numeric|min:0|lte:max_marks|decimal:0,2','assessment_type'=>['required',Rule::in(SchoolAssessments::TYPES)],'lock_version'=>'required|integer|min:0','paper'=>'nullable|array','paper.starts_at'=>'required_with:paper|date_format:H:i','paper.ends_at'=>'required_with:paper|date_format:H:i|after:paper.starts_at','paper.room'=>'nullable|string|max:100']);return response()->json($this->assessments->createTest($r,$d,$id));}
 public function marks(Request $r,int $id){return DB::transaction(fn()=>response()->json($this->assessments->marks($r,$id)));}
 public function change(Request $r,int $id){$this->exam->context($r);$d=$r->validate(['lock_version'=>'required|integer|min:0','action'=>['required',Rule::in(['save','submit','return','publish','revise'])],'reason'=>'nullable|string|max:1000','records'=>'sometimes|array|max:1000','records.*.enrollment_id'=>'required|integer|distinct','records.*.status'=>['required',Rule::in(['pending','present','absent','exempt'])],'records.*.marks'=>'nullable|numeric|min:0|max:100000|decimal:0,2','records.*.remarks'=>'nullable|string|max:1000']);if(isset($d['records']))foreach($d['records'] as &$row)$row['enrollment_id']=(int)$row['enrollment_id'];return response()->json($this->assessments->change($r,$id,$d));}
 public function import(Request $r,int $id){[$test]=$this->exam->test($r,$id,true);$d=$r->validate(['lock_version'=>'required|integer|min:0','file'=>'required|file|max:2048|extensions:csv,xlsx']);if($test->status!=='draft'||$test->lock_version!=$d['lock_version'])$this->exam->fail('Reload the current draft before previewing an import.');$data=$this->assessments->marks($r,$id);$roster=$data['roster']->keyBy('admission_no');$rows=(new StudentImportReader)->read($r->file('file'),['admission_no','status','marks','remarks'],'marks');$seen=[];$errors=[];foreach($rows as $row){$v=$row['data'];$line=$row['line'];$student=$roster->get($v['admission_no']);if(!$student||isset($seen[$v['admission_no']])){$errors[]='Row '.$line.': unknown or duplicate admission number.';continue;}$seen[$v['admission_no']]=true;if(!in_array($v['status'],['pending','present','absent','exempt'],true)){$errors[]='Row '.$line.': invalid status.';continue;}if(mb_strlen($v['remarks'])>1000){$errors[]='Row '.$line.': remarks exceed 1000 characters.';continue;}if($v['status']==='present'){try{$mark=$this->exam->cents($v['marks']);if($mark>$this->exam->cents($test->max_marks))$errors[]='Row '.$line.': marks exceed the maximum.';}catch(\Illuminate\Validation\ValidationException){$errors[]='Row '.$line.': invalid marks; use up to two decimals.';continue;}}elseif($v['marks']!==''){$errors[]='Row '.$line.': non-present status must have blank marks.';continue;}$student->status=$v['status'];$student->marks=$v['marks']===''?null:$v['marks'];$student->remarks=$v['remarks'];}if($errors)throw \Illuminate\Validation\ValidationException::withMessages(['file'=>$errors]);return response()->json(['rows'=>$roster->values(),'imported'=>count($seen),'lock_version'=>$test->lock_version,'message'=>'Import preview ready. Review and save the marks draft; nothing has been written.']);}
 public function cycleDetail(Request $r){$d=$r->validate(['exam_cycle_id'=>'required|integer','section_id'=>'required|integer']);return DB::transaction(fn()=>response()->json($this->reports->cycle($r,$d['exam_cycle_id'],$d['section_id'])));}
 public function candidates(Request $r){$this->exam->context($r);$d=$r->validate(['exam_cycle_id'=>'required|integer','section_id'=>'required|integer']);return response()->json($this->reports->candidates($r,$d));}
 public function consolidate(Request $r){$this->exam->context($r);$d=$r->validate(['exam_cycle_id'=>'required|integer','section_id'=>'required|integer','lock_version'=>'required|integer|min:0','source_digest'=>'required|string|size:64','reason'=>'nullable|string|max:1000']);return response()->json($this->reports->consolidate($r,$d));}
 public function report(Request $r){$d=$r->validate(['kind'=>['required',Rule::in(['test','cycle'])],'id'=>'required|integer']);return DB::transaction(fn()=>response()->json($this->reports->report($r,$d['kind'],$d['id'])));}
 public function share(Request $r){$this->exam->context($r);$d=$r->validate(['kind'=>['required',Rule::in(['test','cycle'])],'id'=>'required|integer','guardian_id'=>'required|integer','recipient_phone'=>'required|string|max:30','confirmed'=>'required|accepted','resend_reason'=>'nullable|string|max:1000']);return response()->json($this->reports->share($r,$d));}
 public function history(Request $r,int $id){[$t]=$this->exam->test($r,$id);[$sid]=$this->exam->context($r);$r->validate(['page'=>'nullable|integer|min:1']);$rows=DB::table('audit_logs as a')->leftJoin('school_memberships as m','m.id','=','a.actor_membership_id')->leftJoin('users as u','u.id','=','m.user_id')->where('a.school_id',$sid)->where('a.target_type','tests')->where('a.target_id',$t->id)->where('a.action','like','exams.%')->orderByDesc('a.id')->paginate(10,['a.id','a.action','a.changes','a.occurred_at','u.name as actor_name']);foreach($rows as $row)$row->changes=json_decode($row->changes,true);return response()->json($rows);}
}
